INSERT INTO node_translations (node_id, lang, label, summary, source_text) SELECT id, 'en', 'Santo André bribery scheme', 'Scheme to extract bribes from public-transport concession holders in Santo André, investigated by the São Paulo State Prosecution Service (MP-SP) and covering the 1997–2001 municipal administration. It led to criminal convictions and to an administrative misconduct (improbidade administrativa) lawsuit.', label || char(10) || COALESCE(summary, '') FROM nodes WHERE id = 'esquema_santo_andre' ON CONFLICT(node_id, lang) DO UPDATE SET label = excluded.label, summary = excluded.summary, source_text = excluded.source_text;
